draw(scale(0.8)*"9", (16.5,0.5));

label(scale(0.8)*"Country", (3,4.5));
label(scale(0.8)*"Brazil", (3,3.5));
label(scale(0.8)*"France", (3,2.5));
label(scale(0.8)*"Peru", (3,1.5));
label(scale(0.8)*"Spain", (3,0.5));

label(scale(0.9)*"Juan's Stamp Collection", (9,0), S);
label(scale(0.9)*"Number of Stamps by Decade", (9,5), N);
[/asy] $80\text{'s}$에 발행된 그의 유럽 우표는 몇 개입니까?

아래는 $y = a \cos bx$의 그래프입니다. 여기서 $a$와 $b$는 양의 상수입니다. $a$를 찾으세요. 

[asy]import TrigMacros;

size(400);

real g(real x)
{
	return (3*cos(4*x));
}

draw(graph(g,-3*pi,3*pi,n=700,join=operator ..),red);
trig_axes(-3*pi,3*pi,-4,4,pi/2,1);
layer();
rm_trig_labels(-5, 5, 2);

label("$1$", (0,1), E);
label("$2$", (0,2), E);
label("$3$", (0,3), E);
label("$-1$", (0,-1), E);
label("$-2$", (0,-2), E);
label("$-3$", (0,-3), E);
[/asy]
